import { RadioButton } from '@/lib/designsystem';

function MyComponent() {
  const [selectedValue, setSelectedValue] = useState('option1');

  return (
    <div>
      <RadioButton
        id="option1"
        name="options"
        value="option1"
        checked={selectedValue === 'option1'}
        onChange={setSelectedValue}
        label="Option 1"
      />
      <RadioButton
        id="option2"
        name="options"
        value="option2"
        checked={selectedValue === 'option2'}
        onChange={setSelectedValue}
        label="Option 2"
      />
    </div>
  );
}
